INSERT INTO `wp_amelia_notifications` VALUES (1,'customer_appointment_approved',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Approved','Dear <strong>%customer_full_name%</strong>,<br><br>You have successfully scheduled\n                     <strong>%service_name%</strong> appointment with <strong>%employee_full_name%</strong>. We are \n                     waiting you at <strong>%location_address% </strong>on <strong>%appointment_date_time%</strong>.\n                     <br><br>Thank you for choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(2,'customer_appointment_pending',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Pending','Dear <strong>%customer_full_name%</strong>,<br><br>The <strong>%service_name%</strong> appointment \n                     with <strong>%employee_full_name%</strong> at <strong>%location_address%</strong>, scheduled for\n                     <strong>%appointment_date_time%</strong> is waiting for a confirmation.<br><br>Thank you for \n                     choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(3,'customer_appointment_rejected',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Rejected','Dear <strong>%customer_full_name%</strong>,<br><br>Your <strong>%service_name%</strong> \n                     appointment, scheduled on <strong>%appointment_date_time%</strong> at <strong>%location_address%\n                     </strong>has been rejected.<br><br>Thank you for choosing our company,\n                     <br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(4,'customer_appointment_canceled',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Canceled','Dear <strong>%customer_full_name%</strong>,<br><br>Your <strong>%service_name%</strong> \n                     appointment, scheduled on <strong>%appointment_date_time%</strong> at <strong>%location_address%\n                     </strong>has been canceled.<br><br>Thank you for choosing our company,\n                     <br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(5,'customer_appointment_rescheduled',NULL,'enabled','email','appointment',NULL,NULL,NULL,'customer','%service_name% Appointment Rescheduled','Dear <strong>%customer_full_name%</strong>,<br><br>The details for your \n                     <strong>%service_name%</strong> appointment with <strong>%employee_full_name%</strong> at \n                     <strong>%location_name%</strong> has been changed. The appointment is now set for \n                     <strong>%appointment_date%</strong> at <strong>%appointment_start_time%</strong>.<br><br>\n                     Thank you for choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(6,'customer_appointment_next_day_reminder',NULL,'enabled','email','appointment','17:00:00',NULL,NULL,'customer','%service_name% Appointment Reminder','Dear <strong>%customer_full_name%</strong>,<br><br>We would like to remind you that you have \n                     <strong>%service_name%</strong> appointment tomorrow at <strong>%appointment_start_time%</strong>.\n                     We are waiting for you at <strong>%location_name%</strong>.<br><br>Thank you for \n                     choosing our company,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(7,'customer_appointment_follow_up',NULL,'enabled','email','appointment',NULL,NULL,1800,'customer','%service_name% Appointment Follow Up','Dear <strong>%customer_full_name%</strong>,<br><br>Thank you once again for choosing our company. \n                     We hope you were satisfied with your <strong>%service_name%</strong>.<br><br>We look forward to \n                     seeing you again soon,<br><strong>%company_name%</strong>',NULL,0,NULL,NULL),(8,'customer_birthday_greeting',NULL,'enabled','email','appointment','17:00:00',NULL,NULL,'custome